function Addon:IsGearCheckBisItem(classFile, specTab, itemId)
	itemId = tonumber(itemId)
	specTab = tonumber(specTab) or 0
	if not itemId or specTab < 1 or not classFile then
		return false
	end
	local set = self.GearCheckBisIds[string.upper(classFile) .. "-" .. tostring(specTab)]
	return set and set[itemId] == true
end
